"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[97],{20097:a=>{a.exports=JSON.parse('{"eyebrow":"Baru di Salat-e-Mustaqeem","lede":"Bacalah, dan halaman mengikuti Anda. Setiap kata menyala keemasan saat Anda melafalkannya, dan yang terlewat menanti Anda di akhir, ditandai dengan lembut.","small":"Gratis. Bisa tanpa internet. Suara Anda tidak pernah keluar dari ponsel Anda.","ctaAppStore":"Unduh di App Store","ctaPlay":"Dapatkan di Google Play","mushafLabel":"Demonstrasi: Al-F\u0101ti\u1e25ah menyala kata demi kata saat dibacakan","status":{"listening":"Mendengarkan\u2026","recited":"Selesai dibaca","review":"Ayat {{n}}: <b>1 kata perlu diulang</b>","well":"Ayat {{n}} \xb7 <b>dibaca dengan baik</b>"},"how":{"kicker":"Cara kerjanya","h2":"Tiga momen, dan tidak ada yang menghalangi Anda dari Al-Qur\u2019an","sub":"Tasm\u012b\u02bf adalah istilah yang dipakai guru tahfiz untuk \u201cperdengarkan hafalanmu kepadaku\u201d. Ia menyimak seperti guru yang sabar: mengikuti, memperhatikan, dan menunggu.","recite":{"h3":"Bacalah","p":"Buka ayat mana pun di pembaca, atau pelajaran Hifz, lalu ketuk pelita. Bacalah sesuai kecepatan Anda, seperti saat menyetor kepada guru."},"follows":{"h3":"Halaman mengikuti","p":"Kata yang sedang Anda baca bercahaya. Halaman berganti sendiri. Ketika ayat selesai, Anda melihat apa yang perlu diulang: gelombang halus di bawah kata yang terlewat, garis kuning keemasan di bawah kata yang dibaca berbeda."},"hear":{"h3":"Dengarkan katanya","p":"Ketuk kata yang ditandai untuk mendengar kata itu saja dari bacaan sang qari. Lalu baca ayat itu lagi. Tidak pernah ada nilai: hanya \u201c2 kata perlu diulang\u201d.","youSaid":"Anda membaca","ayahSays":"Ayatnya berbunyi"}},"hifz":{"kicker":"Untuk hafalan","h2":"Uji saya: ayat tetap tertutup sampai Anda membacanya","sub":"Dari pelajaran Hifz mana pun, aktifkan Uji saya. Ayat disembunyikan, dan setiap kata baru terbuka saat Anda membacanya dengan benar. Inilah yang paling mendekati duduk di hadapan guru Anda, di jam berapa pun pada malam hari.","veilLabel":"Uji saya: kata-kata terbuka saat dibacakan"},"muallim":{"kicker":"Segera hadir","chip":"Eksperimental","h2":"Mu\u02bfallim: tajwid yang diukur dengan kecepatan Anda sendiri","sub1":"Model penyimak kecil yang kami bangun sendiri, berjalan di ponsel seperti bagian Tasm\u012b\u02bf lainnya. Ia mengukur setiap mad dan ghunnah dalam \u1e25arak\u0101t yang dihitung dari bacaan Anda sendiri, sehingga murattal yang pelan dan \u1e25adr yang cepat dinilai dengan ukuran yang sama, lalu menandai bagian yang biasa ditandai guru dengan pensil.","sub2":"Dimulai dengan mad dan ghunnah, lalu qalqalah. Ketika ragu, ia diam: bacaan yang benar tidak boleh ditandai salah. Ia tidak akan menggantikan guru Anda; ia membantu Anda datang dengan siap.","label":"Mu\u02bfallim menandai mad yang dibaca dua harakat padahal yang diminta empat sampai lima","cap":"Mad munfa\u1e63il: dibaca <b>2</b>, seharusnya <b>4\u20135</b>"},"promise":{"kicker":"Janji kami","h2":"Bacaan Anda adalah urusan Anda dengan Allah","items":[{"b":"Di ponsel Anda","span":"Tasm\u012b\u02bf menyimak di perangkat itu sendiri. Suara Anda tidak pernah dikirim ke mana pun, bahkan kepada kami."},{"b":"Tidak pernah direkam","span":"Audio hanya singgah sejenak di memori lalu hilang. Tidak ada yang disimpan."},{"b":"Tanpa internet","span":"Setelah sekali unduh 88 MB, ia berjalan dalam mode pesawat, di masjid, di mana saja."},{"b":"Gratis","span":"Tanpa langganan, tanpa iklan. Sedekah jariyah, insya Allah."}]},"who":{"kicker":"Dibuat untuk","h2":"Setiap pembaca, di setiap tahap","cards":[{"h3":"Santri tahfiz","p":"Murajaah pelajaran sendiri, tangkap kata yang tergelincir, dan datang ke kelas dengan siap."},{"h3":"Anak-anak","p":"Kata-kata emas yang besar, tanda yang lembut, tanpa nilai. Segera: Qaida, huruf demi huruf, dari Alif sampai Y\u0101."},{"h3":"Pemula","p":"Membaca sendirian terasa berat. Tasm\u012b\u02bf menemani Anda, ayat demi ayat, sesuai kecepatan Anda."}],"tag":"Qaida segera hadir"},"honest":{"h3":"Ia memeriksa kata, bukan tajwid","p":"Tasm\u012b\u02bf memberi tahu apakah Anda membaca kata yang benar dengan urutan yang benar. Ia tidak menilai makhraj, mad, atau hukum tajwid lainnya, dan ia bukan guru. Tetaplah menyetor bacaan kepada guru. Tasm\u012b\u02bf ditandai Eksperimental selama kami terus menyempurnakannya."},"faq":{"kicker":"Pertanyaan","h2":"Sebelum Anda mulai","items":[{"q":"Apakah bacaan saya direkam atau diunggah?","a":"Tidak. Seluruh proses menyimak terjadi di ponsel Anda. Audio tidak pernah disimpan dan tidak pernah dikirim, kepada kami ataupun siapa pun."},{"q":"Apakah bisa tanpa internet?","a":"Ya, setelah paket penyimak 88 MB ada di ponsel Anda. Secara bawaan diunduh lewat Wi\u2011Fi; Anda bisa memilih data seluler."},{"q":"Di ponsel apa saja ia berjalan?","a":"iPhone dan ponsel Android yang menjalankan Salat-e-Mustaqeem. Di ponsel lama, ia menyesuaikan diri agar cahaya emasnya tetap mengikuti."},{"q":"Bisakah ia memeriksa tajwid saya?","a":"Belum, tetapi Mu\u02bfallim sedang dalam perjalanan. Ia akan dimulai dengan panjang mad dan ghunnah, diukur dari kecepatan Anda sendiri, dan akan diam setiap kali ragu. Sampai saat itu, setorkan bacaan Anda kepada guru untuk tajwid."},{"q":"Apakah cocok untuk anak-anak?","a":"Ya. Tidak ada nilai, hanya tanda yang lembut. Mode Qaida untuk belajar huruf segera hadir."}]},"final":{"cite":"\u201cDan bacalah Al-Qur\u2019an itu dengan tartil.\u201d Al-Muzzammil 73:4","h2":"Mulailah dengan satu ayat malam ini"},"credit":"Model suara Tasm\u012b\u02bf adalah \u201ctilawi-fastconformer-quran\u201d oleh muhdur, berlisensi CC BY 4.0, disempurnakan dari FastConformer Arab milik NVIDIA (CC BY 4.0). Teks Al-Qur\u2019an: Tanzil."}')}}]);